mapper.select:
select distinct rm.id, u.username, u.usertype, u.windowsaccount,
u.displayname , u.nickname , u.namezhspell, u.namezhshortspell, u.givenname , u.middlename , u.familyname ,
u.gender,
u.authntype, u.mobile, u.email, u.workemail, u.workphonenumber,
u.employeenumber, u.division, u.costcenter, u.organization, u.departmentid, u.department, u.jobtitle, u.joblevel,
rm.createddate,
u.status from mxk_userinfo u, mxk_roles r, mxk_role_member rm where u.instid = #{instId} and r.instid = #{instId} and rm.instid = #{instId}
and rm.roleid = #{roleId} and r.id = #{roleId}
and r.rolename = #{roleName}
and u.username = #{username}
and u.displayname like concat('%',#{displayName},'%')
and rm.memberid = #{memberId}
and rm.type in( 'USER','USER-DYNAMIC') and rm.roleid = r.id and rm.memberid = u.id

select distinct u.*
from mxk_userinfo u
where u.instid = #{instId}
  and not exists (
      select 1
      from mxk_role_member rm
      where rm.instid = #{instId}
        and rm.roleid = #{roleId}
        and rm.memberid = u.id
        and rm.type in ('USER', 'USER-DYNAMIC')
  )

    and u.username = #{username}


    and u.displayname like concat('%', #{displayName}, '%')


    and u.departmentid = #{departmentId}


    and u.jobtitle = #{jobTitle}

select distinct u.id, u.username, u.usertype, u.windowsaccount,
u.displayname , u.nickname , u.namezhspell, u.namezhshortspell, u.givenname , u.middlename , u.familyname ,
u.gender,
u.authntype, u.mobile, u.email, u.workemail, u.workphonenumber,
u.employeenumber, u.division, u.costcenter, u.organization, u.departmentid, u.department, u.jobtitle, u.joblevel,
u.createdby, u.createddate, u.modifiedby, u.modifieddate,
u.status from mxk_userinfo u where u.instid = #{instId} and u.id not in( select rm.memberid from mxk_roles r,mxk_role_member rm where r.instid = #{instId} and rm.instid = #{instId}
and rm.roleid = #{roleId} and r.id = #{roleId}
and r.rolename = #{roleName}
and rm.type in( 'USER','USER-DYNAMIC') and rm.roleid = r.id )
and u.username = #{username}
and u.displayname like concat('%',#{displayName},'%')

select rm.id,
       rm.roleid,
       r.rolename,
       rm.memberid,
       u.username,
       u.displayname,
       rm.type,
       rm.createddate
from mxk_role_member rm
join mxk_roles r on r.id = rm.roleid and r.instid = #{instId}
join mxk_userinfo u on u.id = rm.memberid and u.instid = #{instId}
where rm.instid = #{instId}

    and rm.roleid = #{roleId}


    and u.username = #{username}

order by r.rolename, u.username

select r.*
from mxk_roles r
where r.instid = #{instId}
  and not exists (
      select 1
      from mxk_role_member rm
      join mxk_userinfo u on u.id = rm.memberid and u.instid = #{instId}
      where rm.instid = #{instId}
        and rm.roleid = r.id

            and u.username = #{username}

  )

    and r.rolename like concat('%', #{roleName}, '%')

order by r.rolename

select distinct ir.* from mxk_roles ir, mxk_roles r, mxk_role_member rm where 1 = 1 and rm.roleid = r.id and rm.memberid = ir.id and rm.type in ('ROLE', 'ROLE-DYNAMIC')
and rm.roleid = #{roleId} and r.id = #{roleId}
and r.rolename = #{roleName}

